import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ─────────────────────────────────────────────────────────────────
  // 1. CREATE PLANE GEOMETRY & MATERIAL
  // ─────────────────────────────────────────────────────────────────
  const geometry = new THREE.PlaneGeometry(1.2, 0.75);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });

  const plane = new THREE.Mesh(geometry, material);
  plane.position.set(3.2, 1, 0.06);

  // ─────────────────────────────────────────────────────────────────
  // 2. LOAD TEXTURE (imageUrl required for plane render mode)
  // ─────────────────────────────────────────────────────────────────
  const texturePromise = config.imageUrl
    ? ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
        material.map = tex;
        material.needsUpdate = true;
      })
    : Promise.resolve();

  // ─────────────────────────────────────────────────────────────────
  // 3. CREATE TEXT LABEL ("Journal 3")
  // ─────────────────────────────────────────────────────────────────
  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labelItem = textContent.find((item) => item.role === 'headline') || { text: 'Journal 3' };
  const labelText = typeof labelItem === 'string' ? labelItem : labelItem.text;
  const fontSize = labelItem.typography?.fontSize ?? 39;

  const textMesh = ctx.fontAtlas.createText(labelText, {
    fontSize,
    color: '#e8ecf2',
    align: 'center',
  });
  textMesh.position.z = 0.1;
  plane.add(textMesh);

  // ─────────────────────────────────────────────────────────────────
  // 4. INTERACTION HANDLERS
  // ─────────────────────────────────────────────────────────────────
  const timelines = [];

  const onHover = () => {
    // Kill any existing timeline on this interaction
    timelines.forEach((t) => t.kill());
    timelines.length = 0;

    // Rise-in: subtle 0.15 scene units over 0.7s with power3.out
    const tl = gsap.timeline();
    tl.to(
      plane.position,
      {
        y: plane.position.y + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      },
      0
    );
    timelines.push(tl);
  };

  const onHoverEnd = () => {
    // Return to original position
    timelines.forEach((t) => t.kill());
    timelines.length = 0;

    const tl = gsap.timeline();
    tl.to(
      plane.position,
      {
        y: 1,
        duration: 0.5,
        ease: 'power3.out',
      },
      0
    );
    timelines.push(tl);
  };

  const onClick = () => {
    // Press-down: scale 0.97 over 120ms
    timelines.forEach((t) => t.kill());
    timelines.length = 0;

    const tl = gsap.timeline();
    tl.to(
      plane.scale,
      {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      },
      0
    );
    tl.to(
      plane.scale,
      {
        x: 1,
        y: 1,
        duration: 0.3,
        ease: 'power2.out',
      },
      0.12
    );
    timelines.push(tl);

    // Emit navigate event
    ctx.emit('navigate', { to: 'hub-journal' });
  };

  plane.userData.handlers = {
    onHover,
    onHoverEnd,
    onClick,
  };

  // ─────────────────────────────────────────────────────────────────
  // 5. CLEANUP
  // ─────────────────────────────────────────────────────────────────
  plane.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    geometry.dispose();
    material.dispose();
    if (material.map) {
      material.map.dispose();
    }
  };

  return plane;
}
